import React from "react";
import "./Sidebar.scss";

const Sidebar = () => {
  return (
    <div className="sidebar">
      <ul>
        <li>DEVOLUÇÃO</li>
        <li>STATUS DO PEDIDO</li>
        <li>PERGUNTAS FREQUENTES</li>
        <li>CHAT</li>
        <li>WHATSAPP</li>
        <li>VENDEDOR ONLINE</li>
      </ul>
    </div>
  );
};

export default Sidebar;
